// Unit tests for utils/turkishTime.js. Every hour 00–23 on :00 and :30, written out BY HAND
// from the spoken form (not generated by the helper), plus a few other minutes and the
// inputs the duty roster actually sends ("20:00:00"). Exit 1 on any mismatch.
import { untilTr, dativeSuffix } from '../utils/turkishTime.js'

const HOURS = {
  //   hour spoken       → suffix
  '00': 'a',   // sıfır
  '01': 'e',   // bir
  '02': 'ye',  // iki
  '03': 'e',   // üç
  '04': 'e',   // dört
  '05': 'e',   // beş
  '06': 'ya',  // altı
  '07': 'ye',  // yedi
  '08': 'e',   // sekiz
  '09': 'a',   // dokuz
  '10': 'a',   // on
  '11': 'e',   // on bir
  '12': 'ye',  // on iki
  '13': 'e',   // on üç
  '14': 'e',   // on dört
  '15': 'e',   // on beş
  '16': 'ya',  // on altı
  '17': 'ye',  // on yedi
  '18': 'e',   // on sekiz
  '19': 'a',   // on dokuz
  '20': 'ye',  // yirmi
  '21': 'e',   // yirmi bir
  '22': 'ye',  // yirmi iki
  '23': 'e',   // yirmi üç
}

const cases = []
for (const [h, sfx] of Object.entries(HOURS)) {
  cases.push([`${h}:00`, `${h}.00'${sfx} kadar`])
  cases.push([`${h}:30`, `${h}.30'a kadar`])          // otuz → a, whatever the hour
}
cases.push(
  ['20:00:00', "20.00'ye kadar"],                      // duty_list sends time with seconds
  ['19.00', "19.00'a kadar"],
  ['08:15', "08.15'e kadar"],                          // on beş
  ['08:45', "08.45'e kadar"],                          // kırk beş
  ['08:40', "08.40'a kadar"],                          // kırk
  ['08:50', "08.50'ye kadar"],                         // elli
  ['08:06', "08.06'ya kadar"],                         // altı
  ['8:00', "08.00'e kadar"],
  ['24:00', null], ['nope', null], [null, null],
)

// Suffix rule on its own, so a regression is named precisely.
const words = [['sıfır', 'a'], ['yirmi', 'ye'], ['altı', 'ya'], ['bir', 'e'], ['otuz', 'a'], ['elli', 'ye'], ['kırk', 'a']]

let fail = 0
for (const [input, want] of cases) {
  const got = untilTr(input)
  if (got !== want) { fail++; console.error(`FAIL untilTr(${JSON.stringify(input)}) = ${JSON.stringify(got)}, want ${JSON.stringify(want)}`) }
}
for (const [w, want] of words) {
  const got = dativeSuffix(w)
  if (got !== want) { fail++; console.error(`FAIL dativeSuffix(${w}) = ${got}, want ${want}`) }
}
if (fail) { console.error(`\nturkish time: ${fail} failure(s)`); process.exit(1) }
console.log(`turkish time: OK (${cases.length + words.length} cases; every hour 00–23 on :00 and :30)`)
